<div class="actions" id="bar" hidden><div class="in"><button class="bad" data-g="abort"><svg class="i"><use href="#i-stop"/></svg>Abort this run</button></div></div>
<script>
(function () {
  var K = new URLSearchParams(location.search).get('k') || '';
  var S = null, room = null, busy = false, drafts = {}, nameDraft = '';
  var $ = function (id) { return document.getElementById(id); };
  function esc(s) { return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) { return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]; }); }
  function api(path, body) {
    var opt = body === undefined ? {} : { method: 'POST', body: JSON.stringify(body) };
    return fetch(path + '?k=' + encodeURIComponent(K), opt).then(function (r) { return r.json(); });
  }
  function fail(msg) { var e = $('err'); e.hidden = !msg; e.textContent = msg || ''; }
  function act(path, body) {
    busy = true;
    return api(path, body).then(function (r) { if (!r.ok) fail(r.reason || 'Not accepted'); else fail(''); return load(); })
      .catch(function () { fail('Lost contact with the controller'); }).then(function () { busy = false; });
  }
  function ico(id) { return '<svg class="i"><use href="#i-' + id + '"/></svg>'; }
  var SICO = { pending: 'dot', testing: 'spin', awaiting: 'hand', armed: 'spin', passed: 'check', failed: 'x', skipped: 'skip' };
  var KIND = { light: 'Light', shade: 'Shade', av: 'AV zone', sensor: 'Sensor' };
  var STATUS = { pending: 'Not tested', testing: 'Testing…', awaiting: 'Your verdict', armed: 'Waiting for sensor', passed: 'Passed', failed: 'Failed', skipped: 'Skipped' };
  function readback(it) {
    if (!it.reported && !it.detail) return '';
    var rb = it.readback || {};
    var lines = [];
    if (rb.act && rb.act.level != null) lines.push('Device reports ' + esc(rb.act.level) + '% after acting');
    if (rb.act && rb.act.source != null) lines.push('Room reports source ' + esc(rb.act.source));
    if (rb.restore && rb.restore.level != null) lines.push('Back at ' + esc(rb.restore.level) + '%');
    return '<div class="mono"><span class="' + esc(it.reported) + '">' + esc(it.reported || '') + '</span> ' + esc(it.detail || '') +
      (lines.length ? '<br>' + lines.join('<br>') : '') + '</div>' +
      '<div class="small" style="margin-top:6px">This is what the device reports. Your tap says whether it really happened.</div>';
  }
  function card(it) {
    var h = '<div class="card item s-' + esc(it.status) + '" data-k="' + esc(it.key) + '"><div class="row"><div><div class="name">' + esc(it.name) +
      '</div><div class="kind">' + esc(KIND[it.kind] || it.kind) + '</div></div><span class="badge ' + esc(it.status) + '">' + ico(SICO[it.status] || 'dot') + esc(STATUS[it.status] || it.status) + '</span></div>';
    if (it.status === 'pending') {
      h += '<div class="btns"><button class="primary big" data-a="test">' + ico('play') + 'Test</button><button class="big" data-a="skip">' + ico('skip') + 'Skip</button></div>';
    } else if (it.status === 'testing') {
      h += '<div class="read">' + esc(it.prompt || '') + '</div><div class="btns"><button class="bad big" data-a="fail">' + ico('x') + 'Fail</button></div>';
    } else if (it.status === 'armed') {
      h += '<div class="read">' + esc(it.prompt || '') + '</div><div class="btns"><button class="bad big" data-a="fail">' + ico('x') + 'Fail</button><button class="big" data-a="skip">' + ico('skip') + 'Skip</button></div>';
    } else if (it.status === 'awaiting') {
      h += '<div class="read">' + esc(it.prompt || '') + '</div>' + readback(it) +
        '<input type="text" placeholder="Note (optional)" value="' + esc(drafts[it.key] || '') + '" data-note>' +
        '<div class="btns"><button class="ok big" data-a="pass">' + ico('check') + 'Pass</button><button class="bad big" data-a="fail">' + ico('x') + 'Fail</button><button class="big" data-a="skip">' + ico('skip') + 'Skip</button></div>' +
        '<div class="btns"><button data-a="test">' + ico('redo') + 'Test again</button></div>';
    } else {
      h += readback(it) + (it.note ? '<div class="note">Note: ' + esc(it.note) + '</div>' : '') +
        '<div class="btns"><button data-a="test">' + ico('redo') + 'Test again</button></div>';
    }
    return h + '</div>';
  }
  var DONE = ['passed', 'failed', 'skipped'];
  function heroHtml() {
    var total = S.items.length, done = S.items.filter(function (i) { return DONE.indexOf(i.status) >= 0; }).length;
    var pct = total ? Math.round(done * 100 / total) : 0, C = 2 * Math.PI * 36;
    var cur = S.items.filter(function (i) { return i.status === 'testing' || i.status === 'awaiting' || i.status === 'armed'; })[0];
    return '<div class="card hero"><div class="ring"><svg viewBox="0 0 84 84"><circle class="t" cx="42" cy="42" r="36"/><circle class="v" cx="42" cy="42" r="36" stroke-dasharray="' + C.toFixed(1) + '" stroke-dashoffset="' + (C * (1 - pct / 100)).toFixed(1) + '"/></svg><b>' + pct + '%</b></div>' +
      '<div class="txt"><div class="eyebrow">' + (S.status === 'complete' ? 'All items done' : 'Run in progress') + '</div><div class="big">' + done + ' of ' + total + ' items done</div>' +
      '<div class="meta">' + (cur ? 'Now: ' + esc(cur.name) + ' · ' + esc(cur.room) : (S.current_room ? 'Room: ' + esc(S.current_room) : '')) + '</div></div></div>';
  }
  function render() {
    if (!S) return;
    var c = S.counts;
    $('sub').textContent = (S.read_only ? 'Read-only: ' + S.licence : (S.run_id ? 'Run ' + S.status.replace('_', ' ') : 'No run in progress'));
    $('counts').innerHTML = ['passed', 'failed', 'skipped'].map(function (k) { return '<span class="pill ' + (k === 'passed' ? 'passed' : k === 'failed' ? 'failed' : 'skipped') + '">' + c[k] + ' ' + k + '</span>'; }).join('') + '<span class="pill">' + c.pending + ' open</span>';
    var m = $('main'), h = '';
    var active = S.status === 'running' || S.status === 'complete';
    $('bar').hidden = !active;
    $('hero').innerHTML = active ? heroHtml() : '';
    if (!active) {
      h += '<div class="card"><div class="name">' + (S.status === 'signed_off' ? 'Signed off by ' + esc(S.signed_off_by) : S.status === 'aborted' ? 'Last run aborted' : 'Ready to test') + '</div>' +
        '<input type="text" id="tech" placeholder="Your name" value="' + esc(nameDraft || S.technician) + '">' +
        '<div class="btns"><button class="primary big" data-g="run"' + (S.read_only || !S.rooms.length ? ' disabled' : '') + '>' + ico('play') + 'Start run, all rooms</button></div>' +
        '<div class="small" style="margin-top:12px">Or pick a room to test on its own:</div><div class="chips wrap" style="margin-top:8px">' +
        S.rooms.map(function (r) { return '<button class="chip" data-g="room" data-room="' + esc(r.name) + '"' + (S.read_only ? ' disabled' : '') + '>' + esc(r.name) + ' (' + r.count + ')</button>'; }).join('') + '</div></div>';
      if (!S.rooms.length) h += '<div class="card">The test list is empty. Add devices to rooms in Composer, or add items by hand in the driver properties.</div>';
      m.innerHTML = h;
      return;
    }
    var rooms = S.rooms.filter(function (r) { return S.items.some(function (i) { return i.room === r.name; }); });
    if (!room || !rooms.some(function (r) { return r.name === room; })) room = S.current_room || (rooms[0] && rooms[0].name);
    h += '<div class="chips">' + rooms.map(function (r) {
      var its = S.items.filter(function (i) { return i.room === r.name; });
      var done = its.filter(function (i) { return DONE.indexOf(i.status) >= 0; }).length, open = its.length - done;
      var bad = its.some(function (i) { return i.status === 'failed'; });
      return '<button class="chip' + (r.name === room ? ' on' : '') + (bad ? ' has-fail' : '') + '" data-g="pick" data-room="' + esc(r.name) + '">' + esc(r.name) +
        '<small>' + (open ? open + ' open' : (bad ? 'Done, with failures' : 'Done')) + '</small><span class="bar"><i style="width:' + (its.length ? Math.round(done * 100 / its.length) : 0) + '%"></i></span></button>';
    }).join('') + '</div>';
    h += S.items.filter(function (i) { return i.room === room; }).map(card).join('');
    if (S.status === 'complete') {
      var fails = S.items.filter(function (i) { return i.status === 'failed'; });
      h += '<div class="card"><div class="name">Every item has a verdict</div><div class="small">Signing off stores this run as the as-built record.</div>' +
        '<div class="sum"><div class="p"><b>' + c.passed + '</b>passed</div><div class="f"><b>' + c.failed + '</b>failed</div><div class="s"><b>' + c.skipped + '</b>skipped</div></div>' +
        (fails.length ? '<div class="name failed">Failures</div><ul class="fails">' + fails.map(function (i) { return '<li>' + ico('x') + ' <b>' + esc(i.name) + '</b> <span class="small">' + esc(i.room) + (i.note ? ' · ' + esc(i.note) : '') + '</span></li>'; }).join('') + '</ul>' : '') +
        '<input type="text" id="signer" placeholder="Your name" value="' + esc(nameDraft || S.technician) + '"><div class="btns"><button class="primary big" data-g="signoff"' + (S.read_only ? ' disabled' : '') + '>' + ico('check') + 'Sign off</button></div></div>';
    }
    m.innerHTML = h;
  }
  document.addEventListener('input', function (e) {
    var card = e.target.closest && e.target.closest('.card[data-k]');
    if (e.target.hasAttribute('data-note') && card) drafts[card.getAttribute('data-k')] = e.target.value;
    if (e.target.id === 'tech' || e.target.id === 'signer') nameDraft = e.target.value;
  });
  document.addEventListener('click', function (e) {
    var b = e.target.closest('button'); if (!b || busy) return;
    var g = b.getAttribute('data-g'), a = b.getAttribute('data-a'), c = b.closest('.card[data-k]');
    if (g === 'run') act('run', { technician: nameDraft || (S && S.technician) || '' });
    else if (g === 'room') act('room', { room: b.getAttribute('data-room'), technician: nameDraft || (S && S.technician) || '' }).then(function () { room = b.getAttribute('data-room'); render(); });
    else if (g === 'pick') { room = b.getAttribute('data-room'); render(); act('room', { room: room }); }
    else if (g === 'signoff') act('signoff', { name: nameDraft || (S && S.technician) || '' });
    else if (g === 'abort') { if (confirm('Abort this run? What was recorded is kept as aborted.')) act('abort', {}); }
    else if (a && c) {
      var key = c.getAttribute('data-k');
      if (a === 'test') act('test', { key: key });
      else { var note = drafts[key] || ''; delete drafts[key]; act('mark', { key: key, verdict: a, note: note }); }
    }
  });
  function load() {
    return api('state').then(function (s) { S = s; fail(''); if (!busy || true) render(); }).catch(function () { fail('Lost contact with the controller'); });
  }
  function tick() {
    var typing = document.activeElement && document.activeElement.tagName === 'INPUT';
    var working = S && S.items && S.items.some(function (i) { return i.status === 'testing' || i.status === 'armed'; });
    (typing && !working ? Promise.resolve() : load()).then(function () { setTimeout(tick, working ? 1500 : 4000); });
  }
  tick();
})();
